(root/'requirements.txt').write_text('# CUDA/Kaggle environment only. Torch comes from the GPU image; receipt records it.\ntransformers==5.19.0\npeft==0.21.2\naccelerate==1.15.0\nbitsandbytes==0.50.2\nsentencepiece\nprotobuf\njinja2==3.1.6\n')
